<?php
require __DIR__.'/native_settings.php';
require_once APPPATH.'services/CompanyEmailTemplates.php';
$start=$GLOBALS['essentialChecks'];
$idDefinition=$db->driver()==='sqlite'?'INTEGER PRIMARY KEY AUTOINCREMENT':'INT NOT NULL AUTO_INCREMENT PRIMARY KEY';
$db->query("CREATE TABLE {$p}emailtemplates(emailtemplateid {$idDefinition},type TEXT NOT NULL,slug VARCHAR(100) NOT NULL,language VARCHAR(40),name TEXT NOT NULL,subject TEXT NOT NULL,message TEXT NOT NULL,fromname TEXT NOT NULL,fromemail VARCHAR(100),plaintext INT NOT NULL DEFAULT 0,active INT NOT NULL DEFAULT 0,`order` INT NOT NULL)");
$db->query("INSERT INTO {$p}emailtemplates(type,slug,language,name,subject,message,fromname,fromemail,plaintext,active,`order`) VALUES('client','contact-forgot-password','english','Customized','Principal custom subject','Principal private wording','Principal sender','principal@example.invalid',0,1,0)");
unset($db->data_cache['table_names']);
CompanyEmailTemplateSchema::ensure($db,$p);CompanyEmailTemplateSchema::ensure($db,$p);
$before=$db->query("SELECT * FROM {$p}emailtemplates WHERE emailtemplateid=1")->row();
essentialCheck($before->issuer_id===null,'upgrade preserves historical template origin');
CompanyEmailTemplates::reconcile($db,$p);
foreach([41,82] as $issuer){
 $rows=$db->query("SELECT * FROM {$p}emailtemplates WHERE issuer_id=?",[$issuer])->result_array();
 essentialCheck(count($rows)===164,'each secondary gets factory English/PT-BR templates');
 $reset=$db->query("SELECT * FROM {$p}emailtemplates WHERE issuer_id=? AND slug='contact-forgot-password' AND language='portuguese_br'",[$issuer])->row();
 essentialCheck($reset->subject==='Crie uma nova senha' && !str_contains($reset->message,'Principal private wording') && $reset->fromemail==='','new company has usable public defaults without principal personalization');
}
$db->query("UPDATE {$p}emailtemplates SET subject='Secondary customization' WHERE issuer_id=41 AND slug='contact-forgot-password' AND language='portuguese_br'");
CompanyEmailTemplates::reconcile($db,$p);
essentialCheck($db->query("SELECT subject FROM {$p}emailtemplates WHERE issuer_id=41 AND slug='contact-forgot-password' AND language='portuguese_br'")->row()->subject==='Secondary customization','repeat upgrade preserves secondary customization');
essentialCheck($db->query("SELECT * FROM {$p}emailtemplates WHERE emailtemplateid=1")->row()==$before,'primary customization is not rewritten');
$db->query("DELETE FROM {$p}emailtemplates WHERE issuer_id=82");
$db->failOn="INSERT INTO {$p}emailtemplates";
try{CompanyEmailTemplates::reconcile($db,$p);essentialCheck(false,'expected failure');}catch(RuntimeException $e){essentialCheck(true,'seed storage failure reported');}
$db->failOn=null;
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}emailtemplates WHERE issuer_id=82")->row()->n===0,'failed seed does not commit partial templates');
CompanyEmailTemplates::reconcile($db,$p);
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}emailtemplates WHERE issuer_id=82")->row()->n===164,'retry completes defaults idempotently');
// Exercise the actual core upgrade entry point with the native table present.
IssuerCore::reconcile($db,$p);
IssuerCore::reconcile($db,$p);
essentialCheck($db->query("SELECT * FROM {$p}emailtemplates WHERE emailtemplateid=1")->row()==$before,'core upgrade replay preserves primary template bytes');
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}emailtemplates WHERE issuer_id=41")->row()->n===164,'core upgrade replay does not duplicate company templates');
require_once APPPATH.'services/issuers/IssuerRegistry.php';
$registry=new IssuerRegistry($db,$p);
$new=$registry->saveIssuer(7,['legal_name'=>'Template factory company','tax_id'=>'11222333000181']);
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}emailtemplates WHERE issuer_id=?",[$new])->row()->n===164,'native company registration seeds usable defaults in its transaction');
essentialCheck((new CompanySettingsStorage($db,$p))->get($new,'smtp_password')==='','factory templates do not seed SMTP secrets');
$registryBefore=$db->query("SELECT * FROM {$p}issuers_registry ORDER BY id")->result_array();
$templatesBefore=$db->query("SELECT * FROM {$p}emailtemplates ORDER BY emailtemplateid")->result_array();
$db->failOn="INSERT INTO {$p}emailtemplates";
settingThrows(fn()=>$registry->saveIssuer(7,['legal_name'=>'Failed template company','tax_id'=>'98765432100']),'issuer_storage_failed','registration propagates template storage failure');
$db->failOn=null;
essentialCheck($db->query("SELECT * FROM {$p}issuers_registry ORDER BY id")->result_array()===$registryBefore,'template failure rolls back company creation');
essentialCheck($db->query("SELECT * FROM {$p}emailtemplates ORDER BY emailtemplateid")->result_array()===$templatesBefore,'template failure preserves every existing company template');
$retried=$registry->saveIssuer(7,['legal_name'=>'Retried template company','tax_id'=>'98765432100']);
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}emailtemplates WHERE issuer_id=?",[$retried])->row()->n===164,'registration retry completes its own template set');
$db->query("UPDATE {$p}issuers_registry SET active=1 WHERE id=82");
$originA=CompanyEmailTemplates::findForIssuer($db,$p,41,'contact-forgot-password','portuguese_br');
essentialCheck($originA->subject==='Secondary customization','origin lookup uses A personalization');
CompanySettingsRuntime::run($db,$p,82,12,function()use($db,$p){
 $selected=CompanyEmailTemplates::findForIssuer($db,$p,41,'contact-forgot-password','portuguese_br');
 essentialCheck($selected->subject==='Secondary customization' && CompanySettingsRuntime::issuerId()===82,'explicit mail origin does not borrow or change interactive B context');
});
$db->query("UPDATE {$p}emailtemplates SET message='' WHERE issuer_id=41 AND slug='contact-forgot-password' AND language='portuguese_br'");
essentialCheck(CompanyEmailTemplates::findForIssuer($db,$p,41,'contact-forgot-password','portuguese_br')->language==='english','blank translation falls back inside origin A');
$db->query("UPDATE {$p}emailtemplates SET message='' WHERE issuer_id=41 AND slug='contact-forgot-password' AND language='english'");
essentialCheck(CompanyEmailTemplates::findForIssuer($db,$p,41,'contact-forgot-password','portuguese_br')===null,'missing origin content never borrows principal or B template');
essentialCheck(CompanyEmailTemplates::findForIssuer($db,$p,$primary,'contact-forgot-password','portuguese_br')->subject==='Principal custom subject','legacy primary fallback retains customization');
$db->query("UPDATE {$p}issuers_registry SET active=0 WHERE id=82");
settingThrows(fn()=>CompanyEmailTemplates::findForIssuer($db,$p,82,'contact-forgot-password','english'),'company_settings_issuer_unavailable','inactive origin cannot load templates');
$db->query("UPDATE {$p}issuers_registry SET active=1 WHERE id=82");
$dropIndex=$db->driver()==='sqlite'?'DROP INDEX issuer_template_lookup':"DROP INDEX issuer_template_lookup ON {$p}emailtemplates";
$db->query($dropIndex);
$db->query("CREATE INDEX issuer_template_lookup ON {$p}emailtemplates (slug)");
settingThrows(fn()=>CompanyEmailTemplateSchema::ensure($db,$p),'company_email_template_index_invalid','wrong existing lookup index is not silently accepted');
$db->query($dropIndex);CompanyEmailTemplateSchema::ensure($db,$p);CompanyEmailTemplateSchema::ensure($db,$p);
essentialCheck($db->query("SELECT * FROM {$p}emailtemplates WHERE emailtemplateid=1")->row()==$before,'lookup index retry preserves legacy template data');
echo 'Company template factory/schema: '.($GLOBALS['essentialChecks']-$start).' checks passed ('.$db->driver().').'.PHP_EOL;
